WITH filtered AS (SELECT id, customer_id, started_at, country, UPPER(country) AS country_upper, COALESCE(browser, 'NONE') AS browser_clean FROM sessions WHERE device IN ('tablet', 'desktop', 'mobile')) SELECT id, customer_id, started_at, ROW_NUMBER() OVER (PARTITION BY country ORDER BY started_at DESC, id) AS row_seq, FIRST_VALUE(country) IGNORE NULLS OVER w_ordered AS first_known_country, FIRST_VALUE(country, TRUE) OVER w_running AS first_known_country_2, FIRST_VALUE(country, TRUE) OVER w_running AS first_known_country_3, ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY started_at DESC, id) AS row_seq_2 FROM filtered WINDOW w_ordered AS (ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW), w_running AS (PARTITION BY country ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW);
